for (const item of items) {
  // === 1. Làm sạch trường "Hợp âm" ===
  let hopAm = item.json['Hợp âm'];
  if (typeof hopAm === 'string') {
    const regexTags = /<\/?(span|br)[^>]*>/g;
    hopAm = hopAm.replace(regexTags, '');
    item.json['Hợp âm'] = hopAm;
  }

  // === 2. Phân tích và chuyển đổi trường "Ca sĩ" ===
  const caSiHtml = item.json['Ca sĩ'];
  if (typeof caSiHtml === 'string') {
    // Biểu thức chính quy mới sử dụng `[\s\S]*?` để khớp với cả ngắt dòng
    const regex = /<strong[^>]*>(.*?)<\/strong>[\s\S]*?<span class="badge badge-primary">(.*?)<\/span>[\s\S]*?src="([^"]+)"/g;
    const singerMatches = caSiHtml.matchAll(regex);

    const singersArray = [];

    // Lặp qua từng kết quả khớp để lấy thông tin
    for (const match of singerMatches) {
      const singerName = match[1] ? match[1].trim() : null;
      const tone = match[2] ? match[2].trim() : null;
      const youtubeUrl = match[3] ? match[3].trim() : null;

      singersArray.push({
        'Tên ca sĩ': singerName,
        'Tone': tone,
        'Youtube URL': youtubeUrl
      });
    }

    // Kiểm tra số lượng kết quả để trả về đúng định dạng
    if (singersArray.length === 1) {
      // Nếu chỉ có 1 ca sĩ, trả về một đối tượng JSON
      item.json['Ca sĩ'] = singersArray[0];
    } else if (singersArray.length > 1) {
      // Nếu có nhiều hơn 1 ca sĩ, trả về một mảng
      item.json['Ca sĩ'] = singersArray;
    } else {
      // Nếu không tìm thấy thông tin nào, trả về null
      item.json['Ca sĩ'] = null;
    }
  }
}

return items;

return (async () => {
  const API_BASE = 'https://guitarshare.vn/wp-json/mcp-chord/v1';
  const AUTH = {
    user: 'luckyboyvipmax@gmail.com',
    pass: '58O5 wVH2 stOS GelF PLn2 kbhf'
  };

  // Cache tạm trong node: { "Tên nghệ sĩ": id }
  const artistCache = {};

  /**
   * Tra hoặc tạo artist, bắt lỗi 400 và ghi log
   */
  async function findOrCreateArtist(name) {
    if (!name) return null;

    // 1. Nếu đã cache thì trả luôn
    if (artistCache[name]) {
      return artistCache[name];
    }

    try {
      // 2. GET kiếm các item chứa name
      const getRes = await this.helpers.request({
        method: 'GET',
        url: `${API_BASE}/artists?name=${encodeURIComponent(name)}`,
        json: true,
        auth: AUTH
      });

      // 3. Nếu có exact match → cache + return
      if (Array.isArray(getRes.items)) {
        const exact = getRes.items.find(item => item.name === name);
        if (exact) {
          artistCache[name] = exact.id;
          return exact.id;
        }
      }

      // 4. POST upsert
      const slug = name
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');

      const postRes = await this.helpers.request({
        method: 'POST',
        url: `${API_BASE}/artists/upsert`,
        json: true,
        auth: AUTH,
        body: { name, slug }
      });

      artistCache[name] = postRes.id;
      return postRes.id;
    } catch (err) {
      // Nếu là lỗi 400 → ghi log, trả null, không throw
      const status = err.response?.status || err.statusCode;
      if (status === 400) {
        console.warn(`Artist 400: "${name}" → ${err.response?.body || err.message}`);
        return null;
      }
      // Lỗi khác thì đẩy tiếp để n8n báo
      throw err;
    }
  }

  const output = [];

  // Duyệt từng item input
  for (const item of items) {
    const data = JSON.parse(JSON.stringify(item.json));

    // Composer
    try {
      if (data['Sáng tác']) {
        const cid = await findOrCreateArtist.call(this, data['Sáng tác'].trim());
        data.composerId = cid;
      }
    } catch (e) {
      console.error('Lỗi xử lý composer:', e);
      data.composerId = null;
    }

    // Singers
    if (Array.isArray(data['Ca sĩ'])) {
      for (const s of data['Ca sĩ']) {
        try {
          const sid = await findOrCreateArtist.call(this, s['Tên ca sĩ'].trim());
          s.singerId = sid;
        } catch (e) {
          console.error(`Lỗi xử lý singer "${s['Tên ca sĩ']}":`, e);
          s.singerId = null;
        }
      }
    }

    output.push({ json: data });
  }

  return output;
})();

return (async () => {
  const API_BASE = "https://guitarshare.vn/wp-json/mcp-chord/v1";
  const AUTH = {
    user: "luckyboyvipmax@gmail.com",
    pass: "58O5 wVH2 stOSGelFPLn2kbhf",
  };

  const output = [];

  for (const item of items) {
    const data = item.json;

    // Chuẩn bị các trường cơ bản
    const singerIds   = Array.isArray(data["Ca sĩ"]) ? data["Ca sĩ"].map(s => s.singerId) : [];
    const composerId  = data.composerId;
    const rawTone     = (data["Tone Gốc"] || "").split("").filter(c => c !== "[" && c !== "]").join("").trim();
    let chord_key_root = "", chord_key_type = "major";

    // Xác định root
    if (rawTone[0] && /[A-G]/i.test(rawTone[0])) {
      chord_key_root = rawTone[0].toUpperCase();
      if (rawTone[1] === "#" || rawTone[1] === "b") {
        chord_key_root += rawTone[1];
      }
    }
    // Xác định type
    if (/m(inor)?$/i.test(rawTone)) chord_key_type = "minor";

    const chord_content = data["Hợp âm"] || "";
    const chord_versions = Array.isArray(data["Ca sĩ"])
      ? data["Ca sĩ"].map(s => {
          let mv = s["Youtube URL"];
          if (mv.includes("embed/")) {
            mv = "https://www.youtube.com/watch?v=" + mv.split("embed/")[1].split("?")[0];
          }
          return { mv_link: mv, tone: s.Tone, singers: [s.singerId] };
        })
      : [];

    // Payload chuẩn theo spec
    const body = {
      title: data.title,
      status: "publish",
      singers: singerIds,
      composer: composerId,
      genres: [2679],
      meta: {
        chord_content,
        chord_key_root,
        chord_key_type,
      },
      chord_versions,
    };

    try {
      // Gửi POST
      const res = await this.helpers.request({
        method: "POST",
        url: `${API_BASE}/chords`,
        auth: AUTH,
        json: true,
        body,
      });
      output.push({ json: res });

    } catch (err) {
      // Nếu 400 → log và skip
      const status = err.response?.status || err.statusCode;
      const resp   = err.response?.body || err.message;
      if (status === 400) {
        console.error("❌ Item bị lỗi 400, payload:", JSON.stringify(body));
        console.error("   → Response:", resp);
        // Ghi lại item nhưng đánh dấu lỗi
        output.push({ json: { error: true, status: 400, detail: resp, item: data.title } });
      } else {
        // Lỗi ngoài 400 thì throw tiếp để n8n báo
        throw err;
      }
    }
  }

  return output;
})();

// Lấy item đầu tiên từ mảng đầu vào (đây là cách làm chuẩn và ổn định nhất)
const inputItem = items[0];

// Từ item đó, truy cập vào dữ liệu json, rồi vào mảng 'items'
const conversationsArray = inputItem.json.items;

// --- Phần code còn lại giữ nguyên ---

// Kiểm tra để đảm bảo dữ liệu đầu vào là một mảng
if (!Array.isArray(conversationsArray)) {
  throw new Error("Dữ liệu 'items' không phải là một mảng.");
}

// Lặp qua mảng và tạo cấu trúc item mới cho n8n
const newItems = conversationsArray.map(conversation => {
  return {
    json: conversation
  };
});

// Trả về mảng các item mới
return newItems;

// Lấy item đầu vào
const item = items[0];
const data = item.json;

// Lấy mảng tin nhắn gốc
const originalMessages = data.items;

// --- BƯỚC MỚI: LỌC LẤY 60 TIN NHẮN CUỐI CÙNG ---
// Sử dụng .slice(-60) để lấy 60 phần tử cuối từ mảng.
// Nếu mảng có ít hơn 60, nó sẽ lấy tất cả.
const latest60Messages = originalMessages.slice(-60);

// Hàm trợ giúp để lấy nội dung tin nhắn một cách thông minh (giữ nguyên)
function getMessageContent(msg) {
  if (msg.content_html && msg.content_html.trim() !== '') {
    return msg.content_html;
  }
  switch (msg.type_content) {
    case 'photo':
      return '[Hình ảnh]';
    case 'document':
      return '[Tài liệu]';
    case 'pzl_chat_recommended':
    case 'voip':
      return '[Cuộc gọi]';
    default:
      return `[${msg.type_content}]`;
  }
}

// Dùng .map() trên mảng đã được lọc để tạo cấu trúc bạn muốn
const simplifiedMessages = latest60Messages.map(msg => {
  return {
    nguoiGui: msg.sender_name_fm,
    laNhanVien: msg.staff_name_fm !== false,
    noiDung: getMessageContent(msg),
    thoiGian: msg.inserted_at_fm
  };
});

// Cập nhật lại mảng 'items' bằng mảng đã được lọc và rút gọn
data.items = simplifiedMessages;

// Cập nhật lại số lượng tin nhắn cho chính xác
data.count = simplifiedMessages.length;

// Trả về item đã được cập nhật
return item;

