return $input.all();

// Lấy giá trị max và step từ input (có thể dùng Set node trước đó)
const max = $json.max || 10;   // Nếu chưa có thì mặc định = 100
const step = $json.step || 1;  // Nếu chưa có thì mặc định = 10

const items = [];
for (let i = 0; i <= max; i += step) {
  items.push({ json: { i } });
}

return items;

// Lấy mảng 'conversations' từ dữ liệu đầu vào
const conversations = items[0].json.conversations;

// Sử dụng hàm map để lặp qua từng conversation và tạo một object mới
const results = conversations.map(conv => {

  // --- Lấy thông tin nhân viên phụ trách ---
  let assignedAgentInfo = {
    id: null,
    fullname: 'Chưa gán'
  };
  // Kiểm tra xem có nhân viên nào được gán không
  if (conv.current_assign_users && conv.current_assign_users.length > 0) {
    const agent = conv.current_assign_users[0];
    assignedAgentInfo = {
      id: agent.id,
      fullname: agent.name
    };
  }

  // --- Lấy thông tin tin nhắn cuối cùng và xác định đã rep chưa ---
  let lastMessageText = null;
  let lastMessageSender = { id: null, name: null };
  let hasReplied = false; // Mặc định là chưa trả lời

  // Kiểm tra xem có object 'last_message' không
  if (conv.last_message) {
    lastMessageText = conv.last_message.message;

    if (conv.last_message.from) {
      lastMessageSender = {
        id: conv.last_message.from.id,
        name: conv.last_message.from.name
      };
    }

    // Xác định đã rep chưa bằng cách kiểm tra chiều của tin nhắn
    // 'page_to_user' nghĩa là tin nhắn được gửi từ Trang -> Khách hàng
    // => Đã trả lời
    if (conv.last_message.type === 'page_to_user') {
      hasReplied = true;
    }
  }

  // --- Trả về object đã được rút gọn ---
  return {
    id_conversation: conv.id,
    id_khachhang:conv.from.id,
    tin_nhan_gan_nhat: conv.snippet,
    nguoi_gui: conv.last_sent_by.id, 
    thoi_diem_cap_nhat: conv.updated_at,
    da_seen: !conv.unseen,
    nhan_vien_phu_trach: assignedAgentInfo, // Trả về object chứa id và fullname
    da_rep_chua: hasReplied
  };
});

// Trả về mảng các object đã được rút gọn
return results;
